urlset:
{% for page in pages %}

  {{ page.url }}
  {{ page.last_modified }}
  {{ page.changefreq }}

{% endfor %}

{% for department in departments %}

  https://canonical.com/careers/{{ department.slug }}
  {{ department.last_modified }}
  monthly

{% endfor %}

{% for vacancy in vacancies %}

  https://canonical.com/careers/{{ vacancy.id }}/{{ vacancy.slug }}
  {{ vacancy.date }}
  monthly

{% endfor %}
